definition.script:
pipeline {
  agent { label 'linux' }

  options {
    timestamps()
    disableConcurrentBuilds()
    timeout(time: 20, unit: 'MINUTES')
    buildDiscarder(logRotator(numToKeepStr: '20'))
  }

  triggers {
    cron('H */6 * * *')
  }

  stages {
    stage('Reclaim Docker disk') {
      steps {
        sh '''
          # Back off entirely while a metabuilder/businessplanner base build
          # holds the lock: those jobs do their own per-image prune, and a
          # concurrent prune here previously contributed to base images being
          # evicted mid-run.
          if docker volume inspect mb-base-running >/dev/null 2>&1; then
            echo "mb-base-running lock present -- base build in progress; skipping prune"
            exit 0
          fi

          echo "==> Disk before:"; df -h / | tail -1

          # Conservative on purpose: time filters mean a concurrently running
          # build's recent layers/cache are never touched. Deliberately NOT
          # using image -a / volume prune / system -a, which would evict base
          # images and named volumes that builds and the stack depend on.
          docker builder prune -f --filter until=48h || true
          docker image prune -f || true
          docker container prune -f --filter until=24h || true

          echo "==> Disk after:"; df -h / | tail -1
          docker system df || true
        '''
      }
    }
  }
}
